CASE ssMethodType OF
    SINT#0: 
        (* SystemInitialize for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* InitializeConditions for UnitDelay: '<S1>/Unit Delay' *)
        UnitDelay_DSTATE := LREAL#0.0;
        (* InitializeConditions for DiscreteTransferFcn: '<S1>/Discrete Transfer Fcn1' *)
        DiscreteTransferFcn1_states := LREAL#0.0;
        (* End of SystemInitialize for SubSystem: '<Root>/MPC DMC' *)
        (* '<S2>:1:12' d_hist    = zeros(Ntop, 1); *)
        (* SystemInitialize for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* SystemInitialize for MATLAB Function: '<S1>/Calculating Free Response' *)

        FOR i := DINT#0 TO DINT#147 DO 
            d_hist[i] := LREAL#0.0;
        END_FOR;

        (* End of SystemInitialize for SubSystem: '<Root>/MPC DMC' *)
        (* oldest..newest, IC = 0 *)
        (* '<S2>:1:13' u100_hist = zeros(bigDelay, 1); *)
        (* SystemInitialize for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* SystemInitialize for MATLAB Function: '<S1>/Calculating Free Response' *)

        FOR i := DINT#0 TO DINT#99 DO 
            u100_hist[i] := LREAL#0.0;
        END_FOR;

        (* End of SystemInitialize for SubSystem: '<Root>/MPC DMC' *)
        (* z^-100 delay line, IC = 0 *)
        (* '<S2>:1:14' w_hist    = zeros(Nbot - 1, 1); *)
        (* SystemInitialize for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* SystemInitialize for MATLAB Function: '<S1>/Calculating Free Response' *)

        FOR i := DINT#0 TO DINT#48 DO 
            w_hist[i] := LREAL#0.0;
        END_FOR;

        (* 49-sample history for Tapped Delay1 *)
        (* '<S2>:1:15' u_prev    = 0; *)
        u_prev_f := LREAL#0.0;
        (* End of SystemInitialize for SubSystem: '<Root>/MPC DMC' *)
        (* previous u, for Difference1 *)
        (* '<S3>:1:12' u150_hist = zeros(N, 1); *)
        (* SystemInitialize for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* SystemInitialize for MATLAB Function: '<S1>/Model' *)

        FOR i := DINT#0 TO DINT#149 DO 
            u150_hist[i] := LREAL#0.0;
        END_FOR;

        (* End of SystemInitialize for SubSystem: '<Root>/MPC DMC' *)
        (* z^-150 delay line, IC = 0 *)
        (* '<S3>:1:13' du_hist   = zeros(N - 1, 1); *)
        (* SystemInitialize for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* SystemInitialize for MATLAB Function: '<S1>/Model' *)

        FOR i := DINT#0 TO DINT#148 DO 
            du_hist[i] := LREAL#0.0;
        END_FOR;

        (* 149-sample history (oldest..newest), IC = 0 *)
        (* '<S3>:1:14' u_prev    = 0; *)
        u_prev := LREAL#0.0;
        (* End of SystemInitialize for SubSystem: '<Root>/MPC DMC' *)
        (* previous u, for Difference *)
    SINT#1: 
        (* Outputs for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* MATLAB Function: '<S1>/Calculating Free Response' incorporates:
         *  UnitDelay: '<S1>/Unit Delay' *)
        (* MATLAB Function 'MPC DMC/Calculating Free Response': '<S2>:1' *)
        (* '<S2>:1:2' Ntop = 148; *)
        (* '<S2>:1:3' Nbot = 50; *)
        (* '<S2>:1:4' bigDelay = 100; *)
        (* ---- lazy init on first call only ---- *)
        (* Codegen only allows reading a persistent variable via isempty(...) *)
        (* before it has been assigned; we never read its value before this. *)
        (* '<S2>:1:11' if isempty(d_hist) *)
        (* ---- top branch ---- *)
        (* '<S2>:1:19' d_k = u_k - u_prev; *)
        d_k := UnitDelay_DSTATE - u_prev_f;
        (* Difference1: (z-1)/z *)
        (* '<S2>:1:20' u_prev = u_k; *)
        u_prev_f := UnitDelay_DSTATE;
        (* End of Outputs for SubSystem: '<Root>/MPC DMC' *)
        (* update for next call *)
        (* '<S2>:1:22' v_raw = d_hist; *)
        (* oldest->newest, 148x1 (most recent 148 past d's) *)
        (* '<S2>:1:23' v = flipud(v_raw); *)
        (* Outputs for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* MATLAB Function: '<S1>/Calculating Free Response' incorporates:
         *  UnitDelay: '<S1>/Unit Delay' *)

        FOR i := DINT#0 TO DINT#147 DO 
            v[i] := d_hist[i];
        END_FOR;


        FOR i := DINT#0 TO DINT#73 DO 
            xtmp := v[i];
            v[i] := v[DINT#147 - i];
            v[DINT#147 - i] := xtmp;
        END_FOR;

        (* Selector reverse -> newest->oldest *)
        (* '<S2>:1:24' y1 = H * v; *)
        (* 50x1 *)
        (* '<S2>:1:26' d_hist = [d_hist(2:end); d_k]; *)

        FOR i := DINT#0 TO DINT#146 DO 
            d_hist[i] := d_hist[i + DINT#1];
        END_FOR;

        d_hist[DINT#147] := d_k;
        (* shift in new sample, drop oldest *)
        (* ---- bottom branch ---- *)
        (* '<S2>:1:29' u100_k = u100_hist(1); *)
        u100_k := u100_hist[DINT#0];
        (* oldest entry = u[k-100] *)
        (* '<S2>:1:30' u100_hist = [u100_hist(2:end); u_k]; *)

        FOR i := DINT#0 TO DINT#98 DO 
            u100_hist[i] := u100_hist[i + DINT#1];
        END_FOR;

        u100_hist[DINT#99] := UnitDelay_DSTATE;
        (* shift in current u, drop oldest *)
        (* '<S2>:1:32' w = [w_hist; u100_k]; *)

        FOR i := DINT#0 TO DINT#48 DO 
            w[i] := w_hist[i];
        END_FOR;

        w[DINT#49] := u100_k;
        (* oldest..newest, current (u100_k) last, 50x1 *)
        (* '<S2>:1:33' y2 = SS_N1 .* w; *)
        (* 50x1 *)
        (* '<S2>:1:35' w_hist = [w_hist(2:end); u100_k]; *)

        FOR i := DINT#0 TO DINT#47 DO 
            w_hist[i] := w_hist[i + DINT#1];
        END_FOR;

        w_hist[DINT#48] := u100_k;
        (* MATLAB Function: '<S1>/Model' incorporates:
         *  UnitDelay: '<S1>/Unit Delay' *)
        (* shift in u100_k, drop oldest, for next call *)
        (* ---- combine ---- *)
        (* '<S2>:1:38' f = y1 + y2; *)
        (* 50x1 *)
        (* MATLAB Function 'MPC DMC/Model': '<S3>:1' *)
        (* '<S3>:1:3' N = 150; *)
        (* number of taps / delay length, matches z^-150 and 149+1 taps *)
        (* '<S3>:1:7' SS_1N  = SS(1:N); *)
        (* 1x150 row vector — feeds the "SS(1:N)*u" gain *)
        (* '<S3>:1:8' SS_N1  = SS(N+1); *)
        (* scalar — feeds both "SS(N+1)" gains (ss_gain in the other block too) *)
        (* ---- lazy init on first call only (isempty check is codegen-legal) ---- *)
        (* '<S3>:1:11' if isempty(u150_hist) *)
        (* '<S3>:1:17' if numel(SS_1N) ~= N *)
        (* '<S3>:1:21' if ~isscalar(SS_N1) *)
        (* '<S3>:1:25' SS_1N_row = reshape(SS_1N, 1, N); *)
        (* ensure 1xN row for the dot product *)
        (* ---- top branch ---- *)
        (* '<S3>:1:28' u150_k = u150_hist(1); *)
        u150_k := u150_hist[DINT#0];
        (* oldest entry = u[k-N] *)
        (* '<S3>:1:29' y1 = SS_N1 * u150_k; *)
        (* scalar *)
        (* '<S3>:1:31' u150_hist = [u150_hist(2:end); u_k]; *)
        (* shift in current u, drop oldest *)
        (* ---- bottom branch ---- *)
        (* '<S3>:1:34' du_k = u_k - u_prev; *)
        du_k := UnitDelay_DSTATE - u_prev;
        (* Difference: (z-1)/z *)
        (* '<S3>:1:35' u_prev = u_k; *)
        u_prev := UnitDelay_DSTATE;
        (* End of Outputs for SubSystem: '<Root>/MPC DMC' *)
        (* w = [du_k, du(k-1), ..., du(k-149)], newest->oldest, current first *)
        (* '<S3>:1:38' w = [du_k; flipud(du_hist)]; *)
        (* Outputs for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* MATLAB Function: '<S1>/Model' incorporates:
         *  UnitDelay: '<S1>/Unit Delay' *)

        FOR i := DINT#0 TO DINT#148 DO 
            u150_hist[i] := u150_hist[i + DINT#1];
            x[i] := du_hist[i];
        END_FOR;

        u150_hist[DINT#149] := UnitDelay_DSTATE;

        FOR i := DINT#0 TO DINT#73 DO 
            xtmp := x[i];
            x[i] := x[DINT#148 - i];
            x[DINT#148 - i] := xtmp;
        END_FOR;

        (* 150x1 *)
        (* '<S3>:1:40' y2 = SS_1N_row * w; *)
        (* 1x150 * 150x1 -> scalar *)
        (* '<S3>:1:42' du_hist = [du_hist(2:end); du_k]; *)

        FOR i := DINT#0 TO DINT#147 DO 
            du_hist[i] := du_hist[i + DINT#1];
        END_FOR;

        du_hist[DINT#148] := du_k;
        (* End of Outputs for SubSystem: '<Root>/MPC DMC' *)
        (* shift in current du, drop oldest *)
        (* ---- combine ---- *)
        (* '<S3>:1:45' ym = y1 + y2; *)
        (* scalar *)
        (* Outputs for Atomic SubSystem: '<Root>/MPC DMC' *)
        (* MATLAB Function: '<S1>/Model' *)
        du_k_0[DINT#0] := du_k;

        FOR i := DINT#0 TO DINT#148 DO 
            du_k_0[i + DINT#1] := x[i];
        END_FOR;

        rtb_u := LREAL#0.0;

        FOR i := DINT#0 TO DINT#149 DO 
            rtb_u := (Model_SS[i] * du_k_0[i]) + rtb_u;
        END_FOR;

        (* Sum: '<S1>/Sum2' incorporates:
         *  MATLAB Function: '<S1>/Model' *)
        xtmp := y - ((LREAL#19.906243860199364 * u150_k) + rtb_u);
        (* Gain: '<S1>/Gain1' *)
        rtb_Gain1_idx_0 := LREAL#0.0;

        FOR i := DINT#0 TO DINT#49 DO 
            (* MATLAB Function: '<S1>/Calculating Free Response' *)
            rtb_u := LREAL#0.0;

            FOR i_0 := DINT#0 TO DINT#147 DO 
                rtb_u := (CalculatingFreeResponse_H[(DINT#50 * i_0) + i] * v[i_0]) + rtb_u;
            END_FOR;

            (* Gain: '<S1>/Gain1' incorporates:
             *  MATLAB Function: '<S1>/Calculating Free Response'
             *  Sum: '<S1>/Sum'
             *  Sum: '<S1>/Sum3' *)
            rtb_Gain1_idx_0 := (Gain1_Gain[i * DINT#2] * (b_r - (((LREAL#19.906243860199364 * w[i]) + rtb_u) + xtmp))) + rtb_Gain1_idx_0;
        END_FOR;

        (* Saturate: '<S1>/Saturation' incorporates:
         *  Fcn: '<S1>/Fcn'
         *  Gain: '<S1>/Gain1' *)

        IF rtb_Gain1_idx_0 > LREAL#0.2 THEN 
            xtmp := LREAL#0.2;
        ELSIF rtb_Gain1_idx_0 >= LREAL#-0.2 THEN 
            xtmp := rtb_Gain1_idx_0;
        ELSE 
            xtmp := LREAL#-0.2;
        END_IF;

        (* End of Saturate: '<S1>/Saturation' *)


        (* DiscreteTransferFcn: '<S1>/Discrete Transfer Fcn1' *)
        rtb_u := xtmp - ( -DiscreteTransferFcn1_states);
        (* Saturate: '<S1>/Saturation1' incorporates:
         *  DiscreteTransferFcn: '<S1>/Discrete Transfer Fcn1' *)

        IF rtb_u > LREAL#0.9 THEN 
            xtmp := LREAL#0.9;
        ELSIF rtb_u >= LREAL#0.1 THEN 
            xtmp := rtb_u;
        ELSE 
            xtmp := LREAL#0.1;
        END_IF;

        (* End of Saturate: '<S1>/Saturation1' *)


        (* Update for UnitDelay: '<S1>/Unit Delay' incorporates:
         *  DiscreteTransferFcn: '<S1>/Discrete Transfer Fcn1' *)
        UnitDelay_DSTATE := rtb_u;
        (* Update for DiscreteTransferFcn: '<S1>/Discrete Transfer Fcn1' *)
        DiscreteTransferFcn1_states := rtb_u;
        (* Outport: '<Root>/u' incorporates:
         *  Gain: '<S1>/Gain' *)
        u := LREAL#100.0 * xtmp;
        (* End of Outputs for SubSystem: '<Root>/MPC DMC' *)
END_CASE;
